import { Component, inject } from '@angular/core';

@Component({ selector: 'app-ticket-page', templateUrl: './ticket-page.html' })
export class TicketPage {
  private readonly notifications = inject(NotificationService);
  private readonly toast = inject(ToastService);

  constructor() {
    // Lives as long as the root service, not as long as this page
    this.notifications.messages$.subscribe((m) => this.toast.show(m.text));
  }
}

import { Component, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

@Component({ selector: 'app-ticket-page', templateUrl: './ticket-page.html' })
export class TicketPage {
  private readonly notifications = inject(NotificationService);
  private readonly toast = inject(ToastService);

  constructor() {
    // Completes when this page is destroyed, so the source lets go
    this.notifications.messages$
      .pipe(takeUntilDestroyed())
      .subscribe((m) => this.toast.show(m.text));
  }
}

