import { Component, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';

@Component({
  selector: 'app-inbox-badge',
  template: `<span class="badge">{{ unread() }}</span>`,
})
export class InboxBadge {
  private readonly notifications = inject(NotificationService);
  // No subscribe() to forget: toSignal() unsubscribes on destroy
  readonly unread = toSignal(this.notifications.unread$, { initialValue: 0 });
}
